    ["SETTINGS_TITLE"] = "Paramètres du module",
    ["SETUP_WIZARD_AUDIO_FOCUS_BODY"] = "Réduit temporairement le volume des canaux audio non essentiels pendant la pêche afin que les sons de pêche soient plus faciles à entendre, puis rétablit vos paramètres audio précédents.",
    ["SETUP_WIZARD_AUTO_LOOT_BODY"] = "Active temporairement le « Auto Loot » pour le butin de pêche, puis rétablit votre paramétrage WoW précédent.",
    ["SETUP_WIZARD_BUTTON_BODY"] = "Une interface plus compacte, composée uniquement d’icônes, pour les joueurs qui souhaitent occuper moins d’espace à l’écran.",
    ["SETUP_WIZARD_COMFORT_BODY"] = "Ces options modifient le comportement des commandes de pêche en cas de pêche à cheval, de nage et d’audio du jeu.",
