    ["SETUP_WIZARD_FISH_LABEL"] = "Commencer à pêcher",
    ["SETUP_WIZARD_GEAR_BODY"] = "Avid Angler permet d’équiper un ensemble de pêche enregistré avant de lancer la ligne et de rétablir votre ensemble d’équipement nommé précédent après avoir récupéré un butin.",
