    ["SETUP_WIZARD_GEAR_SAVE_BODY"] = "Enregistre votre équipement actuellement équipé sous le nom d’ensemble « Avid Angler », puis permet de changer d’équipement.",
    ["SETUP_WIZARD_GEAR_TITLE"] = "Équipement de pêche",
