    ["ACH_LOCATION_2096"] = "Dalaran, Norfendre",
    ["ACH_LOCATION_3217"] = "Dalaran, Norfendre",
    ["ACH_GUIDE_1958"] = "Pêchez dans les égouts du ventre du Norfendre Dalaran jusqu'à ce que vous attrapiez le {item:43698}.",
    ["ACH_GUIDE_2094"] = "Pêchez à la fontaine du Norfendre Dalaran jusqu'à ce que toutes les pièces de cuivre répertoriées soient créditées.",
    ["ACH_GUIDE_2095"] = "Pêchez à la fontaine du Norfendre Dalaran jusqu'à ce que toutes les pièces d'argent répertoriées soient créditées.",
    ["ACH_GUIDE_2096"] = "Terminez les succès liés aux pièces de cuivre, d'argent et d'or à la fontaine de Dalaran en Norfendre. Chaque composant a sa propre liste de contrôle des pièces.",
    ["ACH_GUIDE_3217"] = "Terminez les cinq quêtes quotidiennes de pêche différentes proposées par Marcia Chase en Norfendre Dalaran. Revenez à des jours différents pour les quêtes tournantes.",
    ["ACH_GUIDE_1517"] = "Pêchez avec succès dans chacun des dix types de bassins du Norfendre répertoriés. Parcourez la liste de contrôle de la banc de poissons à travers le Norfendre.",
    ["ACH_LOCATION_1517"] = "Zones de cataclysme ; capitales de faction originales",
